final_design:
module TopModule (
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);

    reg [7:0] in_prev;

    always_ff @(posedge clk) begin
        in_prev <= in;
        anyedge <= in ^ in_prev;
    end

endmodule

